emContributions.overall ?? 0,', ' systemBreakdown: labResult.systemContributions', ' },', ' training: trainingResult,', ' nutrition: nutritionResult,', ' diagnostics: diagnosticsResult,', ' overallRaw: Math.min(100, geom(allRaw)),', ' overallNet: Math.min(100, geom(allNet)),', ' systemBreakdown', ' };', '}' ];
